using MediStock.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;
namespace MediStock.Pages.Expiry;[Authorize]public sealed class IndexModel(MediStockDbContext db):PageModel{[BindProperty(SupportsGet=true)]public string?Search{get;set;}[BindProperty(SupportsGet=true)]public string?Filter{get;set;}public IReadOnlyList<ExpiryRow>Items{get;private set;}=[];public async Task OnGetAsync(CancellationToken ct){var today=DateTime.UtcNow.Date;var cutoff=today.AddDays(30);var q=db.StockBatches.AsNoTracking().Where(x=>x.Quantity>0);if(!string.IsNullOrWhiteSpace(Search))q=q.Where(x=>EF.Functions.Like(x.Medicine.Name,$"%{Search.Trim()}%"));if(Filter=="expired")q=q.Where(x=>x.ExpiryDate<today);if(Filter=="soon")q=q.Where(x=>x.ExpiryDate>=today&&x.ExpiryDate<=cutoff);Items=await q.OrderBy(x=>x.ExpiryDate).Select(x=>new ExpiryRow(x.Id,x.Medicine.Name,x.BatchNumber,x.Quantity,x.ExpiryDate,x.ExpiryDate<today?"Expired":x.ExpiryDate<=cutoff?"Expiring soon":"Usable")).ToListAsync(ct);}}
public sealed record ExpiryRow(int Id,string Medicine,string BatchNumber,int Quantity,System.DateTime ExpiryDate,string Status);
